def fix_conf(v):
    return int(v)

sites_out = []
for row in SITES:
    (sid, name, lat, lon, a1, a2, kind, party, conf, first, last, status, baseline, notes) = row
    if sid in CORE:
        continue
    sites_out.append({
        "id": sid,
        "name": name,
        "lat": lat,
        "lon": lon,
        "admin1": a1,
        "admin2": a2,
        "kind": kind,
        "party": party,
        "confidence": fix_conf(conf),
        "firstSeen": f"{first}T00:00:00Z",
        "lastSeen": f"{last}T00:00:00Z",
        "status": status,
        "civilianBaseline": baseline,
        "notes": notes,
    })

# Index for events
by_id = {s["id"]: s for s in sites_out}

# Curated first-seen events (historical, public reporting). Dates are when the change
# first entered the public record, not when we noticed it.
