# Auto events for sites that have no curated row — firstSeen as a pin narrative
covered_sites = {e[4] for e in EVENTS}
for s in sites_out:
    if s["id"] in covered_sites:
        continue
    fam = {
        "airfield": ["flight", "morphology"],
        "strip": ["flight", "morphology"],
        "compound": ["reporting", "morphology"],
        "logistics": ["vehicles", "morphology"],
        "port": ["vehicles", "corridor"],
        "market": ["reporting", "damage"],
        "hospital": ["reporting", "damage"],
        "camp": ["reporting"],
        "crossing": ["corridor", "vehicles"],
        "well": ["corridor"],
        "farm": ["thermal"],
    }.get(s["kind"], ["reporting"])
    neg = s["kind"] in {"farm"}
    EVENTS.append((
        f"ev-auto-{s['id']}",
        s["firstSeen"][:10],
        f"{s['name']} — first public conflict-window record",
        s["notes"] + " First-seen is when this site enters the 2022–2026 public conflict record, not a claim of current occupancy.",
        s["id"],
        fam,
        min(s["confidence"], 2),
        s["lat"],
        s["lon"],
        neg,
    ))

events_out = []
for e in EVENTS:
    eid, day, title, body, site_id, fams, conf, lat, lon, neg = e
    events_out.append({
        "id": f"log-{eid}",
        "firstSeen": f"{day}T00:00:00Z" if "T" not in day else day,
        "lastSeen": f"{day}T00:00:00Z" if "T" not in day else day,
        "title": title,
        "body": body,
        "siteId": site_id if site_id not in {"", None} else None,
        "siteName": None,
        "families": fams,
        "source": "archive",
        "confidence": int(conf),
        "lat": lat,
        "lon": lon,
        "negative": bool(neg),
    })

out = {"sites": sites_out, "events": events_out}
dest = Path("/workspace/src/data/archive.json")
dest.write_text(json.dumps(out, ensure_ascii=False, indent=2), encoding="utf-8")
print(f"sites {len(sites_out)} events {len(events_out)} -> {dest}")
